import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Create a new invoice with enriched line items from the catalogue.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const normalizedTerms = terms ?? 'NET30';
  const dueDateResult = calculateDueDate(issueDate, normalizedTerms);
  if (!dueDateResult.ok) return dueDateResult;

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (line.discountPercent !== undefined) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        enrichedLine.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(enrichedLine);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms: normalizedTerms,
    dueDate: dueDateResult.value,
  });
}

/**
 * Calculate the total for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents, clamped at 0
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  const total = lineTotal(line);
  const discount = roundCents((total * line.discountPercent) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT for a single line item (computed on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents, clamped at 0
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const netAmount = Math.max(0, total - discount);
  const vat = roundCents((netAmount * line.vatRate) / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: object }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} Totals in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVat(line);
  }
  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  vat = roundCents(vat);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total: roundCents(total),
  };
}

/**
 * Add a line to an invoice or increase qty if SKU already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} item
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return discountValidation;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : { ...line }
    );
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }

    newLines = [
      ...invoice.lines.map((line) => ({ ...line })),
      newLine,
    ];
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: { code, amount },
  });
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return ok(addDays(issueDate, 14));
  } else if (terms === 'NET30') {
    return ok(addDays(issueDate, 30));
  } else if (terms === 'EOM') {
    const [year, month] = issueDate.slice(0, 7).split('-');
    const nextMonth = String(parseInt(month) + 1).padStart(2, '0');
    const nextMonthYear = nextMonth === '13' ? String(parseInt(year) + 1) : year;
    const nextMonthMonth = nextMonth === '13' ? '01' : nextMonth;
    const firstDayNextMonth = `${nextMonthYear}-${nextMonthMonth}-01`;
    return ok(addDays(firstDayNextMonth, -1));
  } else {
    return fail('TERMS_INVALID');
  }
}

function validateDiscount(discountPercent) {
  if (discountPercent === undefined) return ok(undefined);
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok(discountPercent);
}

